<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/common.php';
$errors=[]; $selected=(int)($_GET['id']??$_POST['product_id']??0);$products=$pdo->query('SELECT id,name,image_path FROM products ORDER BY name')->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$selected=(int)($_POST['product_id']??0);
 $st=$pdo->prepare('SELECT id FROM products WHERE id=?');$st->execute([$selected]);
 if(!$st->fetch())$errors[]='Vui lòng chọn sản phẩm hợp lệ.';
 if(!isset($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK)$errors[]='Vui lòng chọn một ảnh tải lên.';
 if(!$errors){$file=$_FILES['image'];if($file['size']>3*1024*1024)$errors[]='Ảnh tối đa 3 MB.';else{$finfo=new finfo(FILEINFO_MIME_TYPE);$mime=$finfo->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))$errors[]='Chỉ chấp nhận ảnh JPG, PNG hoặc WebP.';else{$dir=__DIR__.'/uploads/products';if(!is_dir($dir))mkdir($dir,0755,true);$filename=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename))$errors[]='Không thể lưu ảnh lên máy chủ.';else{$st=$pdo->prepare('UPDATE products SET image_path=? WHERE id=?');$st->execute(['uploads/products/'.$filename,$selected]);$_SESSION['flash']=['message'=>'Đã tải ảnh sản phẩm lên thành công.','type'=>'success'];header('Location: products.php');exit;}}}}
}
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tải ảnh sản phẩm</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card shadow-sm mx-auto" style="max-width:680px"><div class="card-header"><h1 class="h4 mb-0">Upload ảnh sản phẩm</h1></div><div class="card-body"><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="mb-3"><label class="form-label">Sản phẩm</label><select required name="product_id" class="form-select"><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" <?=(int)$p['id']===$selected?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Tệp ảnh (JPG, PNG, WebP; tối đa 3 MB)</label><input required type="file" name="image" accept="image/jpeg,image/png,image/webp" class="form-control"></div><button class="btn btn-primary">Tải ảnh</button> <a class="btn btn-outline-secondary" href="products.php">Quay lại</a></form></div></div></main></body></html>
